          "sampleValue": "12%"
        },
        "charged": {
          "type": "boolean",
          "description": "第二个设备是否已经完成充电。",
          "sampleValue": false
        },
        "fillColor": {
          "type": "string",
          "description": "第二个设备电量色块颜色，极低电量使用告警色。",
          "sampleValue": "#ffdb6b42"
        }
      },
      {
        "id": {
          "type": "string",
          "description": "第三个设备的稳定标识，用于已充电勾选项取值。",
          "sampleValue": "tablet"
        },
        "name": {
          "type": "string",
          "description": "第三个设备的短名称。",
          "sampleValue": "平板"
        },
        "level": {
          "type": "number",
          "description": "第三个设备当前电量百分比数值。",
          "sampleValue": 46
        },
        "levelText": {
          "type": "string",
          "description": "第三个设备当前电量展示文本。",
          "sampleValue": "46%"
        },
        "charged": {
          "type": "boolean",
          "description": "第三个设备是否已经完成充电。",
          "sampleValue": true
        },
